def match_parens(lst):
    def is_balanced(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    open_count = lst[0].count('(')
    close_count = lst[0].count(')')
    open_count += lst[1].count('(')
    close_count += lst[1].count(')')

    if open_count != close_count:
        return 'No'

    concatenated = lst[0] + lst[1]
    n = len(concatenated)
    for i in range(1 << n):
        sequence = ''.join([concatenated[j] for j in range(n) if (i & (1 << j)) > 0])
        if is_balanced(sequence):
            return 'Yes'

    return 'No'

